  ('186b6b78-c334-5c53-9675-d7e5ca16b5b4', 7, 2, 62, 'que-te-vaya-bien', 'Wish someone well', 'Que te vaya bien', array['subjuntivo.deseos', 'ojala']::text[], 'informal', 'draft'),
  ('5f6c9abe-859a-5d19-853a-7dc6bcce9c99', 7, 3, 63, 'cuando-llegues', 'Talk about when something will happen', 'Avisame cuando llegues', array['subjuntivo.cuando-futuro', 'terminar']::text[], 'informal', 'draft'),
