  ('063d369c-847e-57b8-8451-b9c4049a1d9e', 7, 6, 66, 'te-recomiendo', 'Give advice', 'Te recomiendo que vayas', array['subjuntivo.recomendar-que', 'es-mejor-que', 'probar']::text[], 'informal', 'draft'),
