insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('35a38f0f-399c-5fdb-8d3e-6e516a149e18', '74698b58-c87a-5870-a6dd-a6652b6da393', 'Quiero que + a new verb form', 'When you want *someone else* to do something, the second verb changes: **quiero que vengas** — *I want you to come*. This form is the **subjunctive**, and *querer que* is where it starts.', 'draft'),
  ('2d43e784-4fe7-5b7a-b775-ad9457aa18f4', '74698b58-c87a-5870-a6dd-a6652b6da393', 'One word for yo and él', '**Venga**, **vaya**, **haga** are both *I* and *he/she*: *quiere que venga* — *he wants me/him to come*. The *que* and the context tell you who.', 'draft'),
  ('5477ef64-8dc9-564c-912e-6162a954a14d', '186b6b78-c334-5c53-9675-d7e5ca16b5b4', 'Que…: a wish', 'A wish is *que* + the subjunctive: **que te vaya bien** — *good luck, hope it goes well*; **que la pases lindo** — *have a great time*; **que tengas buen finde**.', 'draft'),
  ('da34c0b0-6d8a-5dd0-b0d9-899e344f289b', '186b6b78-c334-5c53-9675-d7e5ca16b5b4', 'Ojalá', '**Ojalá** is *I hope*, and the subjunctive follows it: **ojalá que no llueva** — *I hope it doesn''t rain*.', 'draft'),
  ('ee4f763f-c680-5a11-ba55-31f7082d3a0c', '5f6c9abe-859a-5d19-853a-7dc6bcce9c99', 'Cuando, looking ahead', 'About something that hasn''t happened yet, *cuando* takes the subjunctive: **avisame cuando llegues** — *let me know when you get there*. About a habit it doesn''t: *cuando llego, tomo mate*.', 'draft'),
  ('4f6f8f0e-6d84-562a-b6db-ff83d2050223', '8c4c452e-c6f6-5f26-a9a5-ded2342f7c9f', 'Creo que, no creo que', '**Creo que viene** — *I think he''s coming* — keeps the normal verb. Doubt it and the subjunctive comes in: **no creo que venga**.', 'draft'),
  ('3720e015-a831-5b88-af8b-2c4948855038', '8c4c452e-c6f6-5f26-a9a5-ded2342f7c9f', '¿Qué te parece?', '**¿Qué te parece?** — *what do you think?* — and the answer **me parece bien**, **me parece que no**.', 'draft'),
  ('87b289c6-cf4a-5163-a0db-d039023d0990', '52c51646-b698-5749-ae7b-d554ab2e0240', 'No + the subjunctive', 'A command with *no* uses the subjunctive: *vení* but **no vengas**, *andá* but **no vayas**, *decime* but **no me digas**. The pronoun moves to the front: **no te preocupes**.', 'draft'),
  ('8fe89548-6879-50eb-a1b5-202ca80d4885', '52c51646-b698-5749-ae7b-d554ab2e0240', 'No te hagas problema', '**No te hagas problema** — *don''t worry about it* — is what a porteño says when you apologise. **No te olvides** — *don''t forget*.', 'draft'),
  ('6dba3657-5b5a-5fe4-b4f7-b617abe5cac5', '063d369c-847e-57b8-8451-b9c4049a1d9e', 'Recommending', '**Te recomiendo que vayas** — *I''d recommend you go*. **Es mejor que** works the same way: **es mejor que pidas un taxi**.', 'draft'),
  ('3e5b7344-8608-58cc-a353-cae39fa8aefc', '063d369c-847e-57b8-8451-b9c4049a1d9e', 'Vale la pena', '**Vale la pena** — *it''s worth it*. The highest praise a porteño gives a place.', 'draft'),
  ('e80261f8-332a-51cf-8ec3-11e6414d4693', '36b953db-b59d-5c37-8572-47afd0081c48', 'Qué bueno que…', '**¡Qué bueno que estés acá!** — reacting to something *now* takes the subjunctive. **Me alegro** — *I''m glad*; **qué lástima** — *what a shame*.', 'draft'),
  ('98da0042-49a1-5c74-930f-a2b3272b71a6', '36b953db-b59d-5c37-8572-47afd0081c48', 'Me molesta', '**Me molesta que llegue tarde** — *it bugs me that he''s late*. *Molestar* works like *gustar*.', 'draft'),
  ('c585fa33-b562-55de-93f1-7f619cc3b533', 'e21ddcb1-102b-5c87-a018-55c861cdbe47', 'Sé, sabés', '**Sé** — *I know* — has an accent to tell it from *se*. **¿Sabés qué?** — *you know what?* — opens every piece of gossip.', 'draft'),
  ('d292ce1d-68ae-56a4-8a9f-c0cd620f8e18', 'e21ddcb1-102b-5c87-a018-55c861cdbe47', 'No entiendo', '**No entiendo** — *I don''t understand*. **¿Me explicás?** or **explicame** — *can you explain?*', 'draft'),
  ('3fe61f9b-3382-5a80-b860-0a7c427f3415', '39867eb4-c78d-5533-9fa6-0c4b2813b9c0', 'Lunfardo', 'Lunfardo is Buenos Aires slang, born in the port and the tango: **morfar** (to eat), **guita** (money), **fiaca** (laziness), **pilcha** (clothes). Friends, not job interviews.', 'draft'),
  ('e1ff50e4-f00e-575c-a7a6-7c50b9665559', '39867eb4-c78d-5533-9fa6-0c4b2813b9c0', 'Bancar', '**Te banco** — *I''ve got your back*; **no lo banco** — *I can''t stand him*. One verb, and porteños use it for both.', 'draft'),
  ('c5e7d696-e96e-5262-abd7-c802b8a68a8d', '20b6357e-6e5d-58e3-814d-c7acd27bedc2', 'The long goodbye', 'A porteño goodbye is several: **bueno, nos hablamos**, **cuidate**, **un beso**, **que descanses** — and then another *chau* at the door.', 'draft')
